import { useMemo, useState } from 'react'
import { Aviso, Boton, Campo, Cargando, Modal, fecha, hoyLocal, nombre, useDatos } from '../ui'
import { apiErrorMessage } from '../../servicios/errors'
import { bsPago } from './ResumenPagos'
import * as catalogoApi from '../../api/catalogo'
import * as pagosApi from '../../api/pagos'

// Parámetros configurables del formulario (fáciles de ajustar durante la defensa).
const MIN_MODULOS_DESCUENTO = 3
const OPCIONES_CUOTAS = [2, 3, 4, 5, 6, 8, 10, 12]

function sumarMesesSinDesborde(fechaIso, meses) {
  const [anio, mes, dia] = fechaIso.split('-').map(Number)
  const destino = new Date(anio, mes - 1 + meses, 1, 12, 0, 0)
  const ultimoDia = new Date(destino.getFullYear(), destino.getMonth() + 1, 0, 12, 0, 0).getDate()
  destino.setDate(Math.min(dia, ultimoDia))
  return `${destino.getFullYear()}-${String(destino.getMonth() + 1).padStart(2, '0')}-${String(destino.getDate()).padStart(2, '0')}`
}

/** Configura módulos, descuentos y condiciones de pago. */
export default function FormularioOrdenPago({ t, onCerrar, onListo }) {
  const catalogo = useDatos(async () => (await catalogoApi.programas()).data.programas)
  const descuentos = useDatos(async () => (await pagosApi.descuentos()).data.descuentos)
  const programa = catalogo.datos?.find((p) => p.modulos.some((m) => m.codigo === t.modulo_codigo))

  const [modulos, setModulos] = useState([t.modulo_codigo])
  const [dctos, setDctos] = useState([])
  const [formaPago, setFormaPago] = useState('unico')
  const [cuotas, setCuotas] = useState(3)
  const [vence, setVence] = useState(() => hoyLocal(1))
  const [error, setError] = useState(null)
  const [enviando, setEnviando] = useState(false)

  const totalModulosPrograma = programa?.modulos?.length || 0
  const cumpleTresModulos = modulos.length >= MIN_MODULOS_DESCUENTO
  const cumpleProgramaCompleto = totalModulosPrograma > 0 && modulos.length === totalModulosPrograma

  function actualizarModulos(siguiente) {
    setModulos(siguiente)
    const cumpleTres = siguiente.length >= MIN_MODULOS_DESCUENTO
    const cumpleComp = totalModulosPrograma > 0 && siguiente.length === totalModulosPrograma
    // Depura de forma síncrona los descuentos incompatibles con la nueva selección de módulos.
    setDctos((prev) => prev.filter((codigo) => {
      if (codigo === '3_MAS_MODULOS' && !cumpleTres) return false
      if (codigo === 'PROGRAMA_COMPLETO' && !cumpleComp) return false
      return true
    }))
  }

  function seleccionarModulo(codigo) {
    actualizarModulos(modulos.includes(codigo) ? modulos.filter((x) => x !== codigo) : [...modulos, codigo])
  }

  function alternarProgramaCompleto(marcado) {
    if (!programa) return
    actualizarModulos(marcado ? programa.modulos.map((m) => m.codigo) : [])
  }

  function alternarDescuento(codigo) {
    setDctos((prev) => (prev.includes(codigo) ? prev.filter((x) => x !== codigo) : [...prev, codigo]))
  }

  const subtotal = useMemo(
    () => (programa?.modulos || []).filter((m) => modulos.includes(m.codigo)).reduce((s, m) => s + Number(m.precio), 0),
    [programa, modulos],
  )

  const descuentosAplicados = useMemo(
    () => (descuentos.datos || []).filter((d) => dctos.includes(d.codigo)),
    [descuentos.datos, dctos],
  )

  // Conserva exactamente la fórmula de acumulación del backend (cada descuento redondeado a 2 decimales sobre el subtotal).
  const importeDescontado = useMemo(
    () => descuentosAplicados.reduce((s, d) => s + Math.round(subtotal * Number(d.porcentaje)) / 100, 0),
    [descuentosAplicados, subtotal],
  )

  const total = Math.max(Math.round((subtotal - importeDescontado) * 100) / 100, 0)
  const cantidadCuotas = formaPago === 'unico' ? 1 : cuotas

  const vistaCuotas = useMemo(() => {
    if (total <= 0 || !vence) return []
    const base = Math.floor((total / cantidadCuotas) * 100) / 100
    return Array.from({ length: cantidadCuotas }, (_, idx) => {
      const nro = idx + 1
      const importe = nro === cantidadCuotas ? Math.round((total - base * (cantidadCuotas - 1)) * 100) / 100 : base
      return { nro, fecha: sumarMesesSinDesborde(vence, idx), importe }
    })
  }, [total, cantidadCuotas, vence])

  async function generarOrden(e) {
    e.preventDefault()
    if (!modulos.length || enviando) return
    setEnviando(true)
    setError(null)
    try {
      const { data } = await pagosApi.crearOrden(t.nro_tarjeta, {
        modulos,
        descuentos: dctos,
        cuotas: cantidadCuotas,
        primer_vencimiento: vence,
      })
      onListo(data.mensaje)
    } catch (err) {
      setError(apiErrorMessage(err))
      setEnviando(false)
    }
  }

  return (
    <Modal ancho titulo="Generar orden de pago" descripcion="Configura módulos, descuentos, forma de pago y vencimientos." onCerrar={onCerrar}>
      {!programa ? <Cargando /> : (
        <form className="grid gap-5" onSubmit={generarOrden}>
          {/* A. Información comercial */}
          <section className="grid grid-cols-2 gap-3 rounded-ui border border-filete bg-niebla-2 p-3.5 max-movil:grid-cols-1">
            <div>
              <span className="text-xs text-tinta-suave">Prospecto</span>
              <strong className="block">{nombre(t.prospecto)}</strong>
            </div>
            <div>
              <span className="text-xs text-tinta-suave">Programa educativo</span>
              <strong className="block">{programa.nombre}</strong>
            </div>
          </section>

          {/* B. Selección de módulos */}
          <fieldset className="grid gap-2.5 min-w-0">
            <legend className="mb-1 font-bold">Módulos contratados</legend>
            <label className="check font-semibold">
              <input
                type="checkbox"
                checked={cumpleProgramaCompleto}
                onChange={(e) => alternarProgramaCompleto(e.target.checked)}
              />
              Seleccionar programa completo ({totalModulosPrograma} módulos)
            </label>
            <div className="grid gap-2 rounded-ui border border-filete p-3">
              {programa.modulos.map((m, i) => (
                <label key={m.codigo} className="check justify-between gap-2">
                  <span className="flex items-center gap-2.5">
                    <input
                      type="checkbox"
                      checked={modulos.includes(m.codigo)}
                      onChange={() => seleccionarModulo(m.codigo)}
                    />
                    <span>{String(i + 1).padStart(2, '0')} · {m.nombre}</span>
                  </span>
                  <b className="text-sm tabular-nums">{bsPago(m.precio)}</b>
                </label>
              ))}
            </div>
            <div className="flex flex-wrap justify-between gap-2 text-sm text-tinta-suave">
              <span>{modulos.length} {modulos.length === 1 ? 'módulo seleccionado' : 'módulos seleccionados'}</span>
              <span>Subtotal: <b className="text-tinta tabular-nums">{bsPago(subtotal)}</b></span>
            </div>
          </fieldset>

          {/* C. Descuentos */}
          <fieldset className="grid gap-2.5 min-w-0">
            <legend className="mb-1 font-bold">Descuentos</legend>
            <div className="grid gap-2 rounded-ui border border-filete p-3">
              {(descuentos.datos || []).map((d) => {
                const esTres = d.codigo === '3_MAS_MODULOS'
                const esCompleto = d.codigo === 'PROGRAMA_COMPLETO'
                const deshabilitado = (esTres && !cumpleTresModulos) || (esCompleto && !cumpleProgramaCompleto)
                const ayudaRegla = esTres && !cumpleTresModulos
                  ? 'Selecciona al menos tres módulos para aplicar este descuento.'
                  : esCompleto && !cumpleProgramaCompleto
                    ? 'Selecciona todos los módulos para aplicar este descuento.'
                    : null
                return (
                  <div key={d.codigo} className="grid gap-0.5">
                    <label className={`check ${deshabilitado ? 'opacity-60' : ''}`}>
                      <input
                        type="checkbox"
                        disabled={deshabilitado}
                        checked={dctos.includes(d.codigo)}
                        onChange={() => alternarDescuento(d.codigo)}
                      />
                      <span>{d.nombre} — <b>{Number(d.porcentaje)}%</b></span>
                    </label>
                    {ayudaRegla && <small className="pl-7 text-xs text-tinta-suave">{ayudaRegla}</small>}
                  </div>
                )
              })}
            </div>
          </fieldset>

          {/* D/E. Resumen económico */}
          <section className="rounded-ui border border-filete bg-niebla-2 p-4 grid gap-1.5 text-sm">
            <div className="flex justify-between gap-2">
              <span className="text-tinta-suave">Subtotal</span>
              <span className="tabular-nums">{bsPago(subtotal)}</span>
            </div>
            <div className="flex justify-between gap-2">
              <span className="text-tinta-suave">
                Descuentos ({descuentosAplicados.length ? descuentosAplicados.map((d) => `${d.nombre} ${Number(d.porcentaje)}%`).join(' + ') : 'Ninguno'})
              </span>
              <span className="tabular-nums text-exito">- {bsPago(importeDescontado)}</span>
            </div>
            <div className="mt-1 flex justify-between gap-2 border-t border-filete pt-2 text-base font-bold">
              <span>Total final</span>
              <span className="text-lg tabular-nums text-acento-texto">{bsPago(total)}</span>
            </div>
          </section>

          {/* F. Forma de pago */}
          <div className="grid grid-cols-3 gap-4 max-movil:grid-cols-1">
            <Campo etiqueta="Forma de pago" requerido>
              <select value={formaPago} onChange={(e) => setFormaPago(e.target.value)}>
                <option value="unico">Pago único</option>
                <option value="cuotas">Pago en cuotas</option>
              </select>
            </Campo>
            {formaPago === 'cuotas' && (
              <Campo etiqueta="Cantidad de cuotas" requerido>
                <select value={cuotas} onChange={(e) => setCuotas(Number(e.target.value))}>
                  {OPCIONES_CUOTAS.map((n) => (
                    <option key={n} value={n}>Plan de {n} cuotas</option>
                  ))}
                </select>
              </Campo>
            )}
            <Campo etiqueta={formaPago === 'unico' ? 'Vencimiento' : 'Primer vencimiento'} requerido>
              <input type="date" min={hoyLocal()} required value={vence} onChange={(e) => setVence(e.target.value)} />
            </Campo>
          </div>

          {/* G. Vista previa de cuotas */}
          {formaPago === 'cuotas' && vistaCuotas.length > 0 && (
            <div className="grid gap-1.5">
              <strong className="text-sm">Vista previa del plan</strong>
              <div className="tabla-marco">
                <table className="tabla">
                  <thead>
                    <tr>
                      <th>Cuota</th>
                      <th>Vencimiento</th>
                      <th className="num">Importe</th>
                    </tr>
                  </thead>
                  <tbody>
                    {vistaCuotas.map((c) => (
                      <tr key={c.nro}>
                        <td className="tabular-nums">{c.nro} de {cantidadCuotas}</td>
                        <td className="tabular-nums">{fecha(c.fecha)}</td>
                        <td className="num">{bsPago(c.importe)}</td>
                      </tr>
                    ))}
                    <tr className="font-bold">
                      <td colSpan={2}>Total</td>
                      <td className="num">{bsPago(total)}</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {!modulos.length && <Aviso tipo="error">Selecciona al menos un módulo para generar la orden.</Aviso>}
          <Aviso tipo="error">{error}</Aviso>

          {/* H. Botones finales */}
          <div className="acciones">
            <button type="button" className="btn btn-secundario" disabled={enviando} onClick={onCerrar}>Cancelar</button>
            <Boton type="submit" className="btn-primario" cargando={enviando} disabled={!modulos.length || total <= 0}>
              {enviando ? 'Generando orden...' : 'Confirmar orden de pago'}
            </Boton>
          </div>
        </form>
      )}
    </Modal>
  )
}

methods.body:
if (! $usuario) {
    return false;
}

$acceso = self::permisos($usuario->rol)[$recurso] ?? null;

return $acceso !== null && Permiso::NIVELES[$acceso] >= Permiso::NIVELES[$nivel];

$ofertas = $this->externo->ofertas();
$media = $ofertas->keyBy('external_modulo_id');
$programasExternos = $ofertas->pluck('programa', 'programa.id');
$termino = mb_strtolower(trim((string) $r->query('buscar', '')));

$programas = $this->catalogo->programasAbiertos()
    ->map(function (Programa $programa) use ($media, $programasExternos, $termino) {
        $modulos = $programa->modulos
            ->filter(fn (CatalogoCache $modulo) => $termino === '' || str_contains(
                mb_strtolower($programa->nombre.' '.$modulo->nombre.' '.$modulo->descripcion),
                $termino,
            ))
            ->map(fn (CatalogoCache $modulo) => [
                'codigo' => $modulo->codigo,
                'anuncio_codigo' => $modulo->anuncio_codigo,
                'nombre' => $modulo->nombre,
                'descripcion' => $modulo->descripcion,
                'precio' => (float) $modulo->precio,
                'duracion' => $media[$modulo->codigo]['modulo']['duracion'] ?? null,
                'imagen' => $media[$modulo->codigo]['imagen'] ?? null,
            ])->values();

        return [
            'codigo' => $programa->codigo,
            'nombre' => $programa->nombre,
            'descripcion' => $programasExternos[$programa->codigo]['descripcion'] ?? null,
            'area' => $programasExternos[$programa->codigo]['area'] ?? 'Otros programas',
            'imagen' => $programasExternos[$programa->codigo]['imagen'] ?? null,
            'precio_total' => round($modulos->sum('precio'), 2),
            'modulos' => $modulos,
        ];
    })
    ->filter(fn ($programa) => $programa['modulos']->isNotEmpty())
    ->values();

return response()->json(['programas' => $programas]);

$duraciones = ['24 horas', '32 horas', '40 horas', '48 horas', '60 horas'];

return [
    'nombre' => $nombre,
    'precio' => $precio,
    'duracion' => $duraciones[crc32($slug) % count($duraciones)],
    'imagen' => asset("catalogo-demo/modulo-{$slug}.svg"),
    'descripcion' => $descripcion,
];

$datos = $r->validated();
$modulos = $this->modulosSolicitados($datos);

try {
    $resultado = $this->prospectos->transaccion(function () use ($datos, $modulos) {
        $prospecto = $this->prospectos->encontrarPorDocumentoOCorreoBloqueado($datos['documento'], $datos['correo']);
        $creado = ! $prospecto;

        if ($creado) {
            $prospecto = $this->prospectos->crear($this->soloPersona($datos) + ['origen' => 'Web', 'estado' => 'Nuevo', 'fecha_registro' => now()]);
        } elseif ($prospecto->documento !== $datos['documento'] || strcasecmp($prospecto->correo, $datos['correo']) !== 0) {
            throw ValidationException::withMessages(['correo' => 'Ese correo o carnet ya está registrado con otros datos. Comuníquese con coordinación.']);
        }

        $intereses = $this->crearIntereses($prospecto, $modulos);
        $nuevos = $intereses->filter(fn ($interes) => $interes->wasRecentlyCreated)->values();
        $repetidos = $intereses->reject(fn ($interes) => $interes->wasRecentlyCreated)->values();

        if ($nuevos->isEmpty()) {
            $modulosTexto = $repetidos->pluck('modulo_nombre')->implode(', ');
            $mensaje = $repetidos->count() === 1
                ? "Ya registraste tu interés en {$modulosTexto}. Un asesor ya tiene tu solicitud en seguimiento."
                : "Ya tienes intereses registrados en los módulos seleccionados: {$modulosTexto}.";

            throw new ReglaNegocioException($mensaje, 422);
        }

        return [$creado, $nuevos, $repetidos];
    });
} catch (UniqueConstraintViolationException) {
    throw ValidationException::withMessages(['correo' => 'Su registro se está procesando. Intente nuevamente en unos segundos.']);
}

[$nuevo, $nuevos, $repetidos] = $resultado;
$mensaje = $repetidos->isEmpty()
    ? 'Interés registrado correctamente.'
    : 'Se registró su interés en '.$nuevos->pluck('modulo_nombre')->implode(', ')
        .'. Ya estaba registrado: '.$repetidos->pluck('modulo_nombre')->implode(', ').'.';

return response()->json([
    'mensaje' => $mensaje,
    'detalle' => 'Un asesor se comunicará con usted por WhatsApp.',
    'nuevo_prospecto' => $nuevo,
], $nuevo ? 201 : 200);

$this->autorizarAlta($r->usuario());
$datos = $r->validated();

$prospecto = $this->prospectos->transaccion(function () use ($datos) {
    $prospecto = $this->prospectos->crear($this->soloPersona($datos) + ['origen' => $datos['origen'], 'estado' => 'Nuevo', 'fecha_registro' => now()]);
    if (! empty($datos['modulo_codigo']) || ! empty($datos['programa_codigo'])) {
        $this->crearIntereses($prospecto, $this->modulosSolicitados($datos));
    }

    return $prospecto;
});

return response()->json(['mensaje' => 'Prospecto registrado correctamente.', 'prospecto' => $this->prospectos->conIntereses($prospecto)], 201);

$registro = $this->prospectos->obtener($prospecto);
ReglaNegocioException::si(! $this->prospectos->estaDentroDeCartera($registro, $r->usuario()), 'Este prospecto no está dentro de su cartera.', 403);
$this->prospectos->actualizar($registro, $r->validated());

return response()->json(['mensaje' => 'Datos del prospecto actualizados.', 'prospecto' => $this->prospectos->actualizado($registro)]);

$usuario = $r->usuario();
$datos = $r->validated();
$registro = $this->prospectos->obtener($prospecto);
ReglaNegocioException::si($usuario->rol === 'vendedor' && ! $this->prospectos->estaDentroDeCartera($registro, $usuario), 'Este prospecto no está dentro de su cartera.', 403);

$intereses = $this->prospectos->transaccion(function () use ($registro, $datos, $usuario) {
    $vendedor = $usuario->rol === 'vendedor' ? $usuario->correo : null;

    return $this->crearIntereses($registro, $this->modulosSolicitados($datos), $vendedor);
});

if ($intereses->every(fn ($interes) => ! $interes->wasRecentlyCreated)) {
    throw ValidationException::withMessages([
        'modulo_codigo' => 'El prospecto ya tiene registrado ese interés.',
    ]);
}

return response()->json(['mensaje' => 'Interés registrado.', 'intereses' => $intereses], 201);

$this->autorizarAlta($usuario);
$filas = $this->leerCsv($csv);
$cabecera = array_shift($filas) ?? [];
$faltan = array_values(array_diff(self::CAMPOS_CSV, $cabecera));

ReglaNegocioException::si((bool) $faltan, 'Al archivo le faltan columnas obligatorias: '.implode(', ', $faltan).'.', 422, [
    'columnas_requeridas' => self::CAMPOS_CSV,
    'errores' => array_map(fn ($c) => ['columna' => $c, 'error' => 'Columna obligatoria ausente'], $faltan),
]);
if (count($cabecera) !== count(array_unique($cabecera))) {
    throw ValidationException::withMessages(['csv' => 'El archivo tiene columnas repetidas.']);
}

$errores = [];
$registros = [];
foreach ($filas as $i => $valores) {
    $linea = $i + 2;
    if ($valores === [null] || $valores === ['']) {
        continue;
    }
    if (count($valores) !== count($cabecera)) {
        $errores[] = ['fila' => $linea, 'error' => 'La fila no tiene la misma cantidad de columnas que la cabecera'];

        continue;
    }
    $fila = array_combine($cabecera, array_map(fn ($v) => trim((string) $v), $valores));
    $fila['correo'] = mb_strtolower($fila['correo']);
    $fila['origen'] = collect(self::ORIGENES)->first(fn ($o) => strcasecmp($o, $fila['origen']) === 0) ?? $fila['origen'];

    $validador = validator($fila, self::reglasPersona() + ['origen' => ['required', Rule::in(self::ORIGENES)]], [], self::ATRIBUTOS);
    foreach ($validador->errors()->messages() as $columna => $mensajes) {
        $errores[] = ['fila' => $linea, 'columna' => $columna, 'error' => $mensajes[0]];
    }
    if ($this->prospectos->existeDocumentoOCorreo($fila['documento'], $fila['correo'])) {
        $errores[] = ['fila' => $linea, 'error' => 'El carnet o el correo ya están registrados'];
    }
    $fila['modulos'] = collect();
    if (! empty($fila['modulo_codigo']) || ! empty($fila['programa_codigo'])) {
        $fila['modulos'] = $this->prospectos->modulosSolicitados($fila);
        if ($fila['modulos']->isEmpty()) {
            $errores[] = ['fila' => $linea, 'columna' => 'modulo_codigo', 'error' => 'El módulo o programa no existe o no está abierto'];
        }
    }
    $registros[] = $fila;
}

if (! $registros) {
    $errores[] = ['fila' => 2, 'error' => 'El archivo no contiene registros'];
}
foreach (['documento' => 'Carnet', 'correo' => 'Correo'] as $campo => $nombre) {
    foreach (collect($registros)->pluck($campo)->filter()->duplicates()->unique() as $repetido) {
        $errores[] = ['columna' => $campo, 'error' => "{$nombre} repetido dentro del archivo: {$repetido}"];
    }
}

ReglaNegocioException::si((bool) $errores, 'El archivo tiene errores; no se cargó ningún prospecto.', 422, [
    'columnas_requeridas' => self::CAMPOS_CSV, 'columnas_opcionales' => self::CAMPOS_CSV_INTERES, 'errores' => $errores,
]);

$this->prospectos->transaccion(function () use ($registros) {
    foreach ($registros as $fila) {
        $prospecto = $this->prospectos->crear($this->soloPersona($fila) + ['origen' => $fila['origen'], 'estado' => 'Nuevo', 'fecha_registro' => now()]);
        $this->crearIntereses($prospecto, $fila['modulos']);
    }
});

return count($registros);

$modulos = $this->prospectos->modulosSolicitados($datos);

if ($modulos->isEmpty() || (isset($datos['modulo_codigos']) && $modulos->count() !== count($datos['modulo_codigos']))) {
    throw ValidationException::withMessages(['modulo_codigos' => 'Uno o más módulos seleccionados ya no están disponibles. Revise la selección.']);
}
if (isset($datos['modulo_codigos']) && $modulos->pluck('programa_codigo')->unique()->count() > 1) {
    throw ValidationException::withMessages(['modulo_codigos' => 'Seleccione módulos de un solo programa por registro.']);
}

return $modulos;

// Todas las tarjetas de un prospecto quedan con el mismo vendedor (si ya tiene uno).
$vendedor ??= $this->prospectos->vendedorExistente($prospecto);

return $modulos->map(fn (CatalogoCache $m) => $this->prospectos->crearInteres($prospecto, $m, $vendedor));

$texto = preg_replace('/^\xEF\xBB\xBF/', '', $texto);
$separador = substr_count(strtok($texto, "\n") ?: '', ';') > substr_count(strtok($texto, "\n") ?: '', ',') ? ';' : ',';
$stream = fopen('php://temp', 'r+');
fwrite($stream, $texto);
rewind($stream);
$filas = [];
while (($valores = fgetcsv($stream, 0, $separador, '"', '')) !== false) {
    $filas[] = $valores;
}
fclose($stream);

if ($filas) {
    $filas[0] = array_map(fn ($c) => match ($c = Str::ascii(Str::lower(trim((string) $c)))) {
        'nombres' => 'nombre', 'apellidos' => 'apellido', 'ci', 'carnet' => 'documento', 'celular' => 'telefono', 'email' => 'correo',
        'modulo' => 'modulo_codigo', 'programa' => 'programa_codigo',
        default => $c,
    }, $filas[0]);
}

return $filas;

