import { useEffect, useState } from 'react'
import { AlertTriangle, CheckCircle2, Clock, CreditCard, ExternalLink, Printer, XCircle } from 'lucide-react'
import { Aviso, CabeceraPagina, Cargando, Etiqueta, bs, fecha } from '../componentes/ui'
import { apiErrorMessage } from '../servicios/errors'
import { useAuth } from '../servicios/auth'
import { go, useAppRoute } from '../servicios/navigation'
import * as pagosApi from '../api/pagos'

/** CU6: pantalla de retorno oficial tras Stripe Checkout (payment o setup). Verifica siempre con Stripe vía Laravel. */
export default function PPagoConfirmacion() {
  const { query } = useAppRoute()
  const sesion = useAuth()
  const sessionId = query.session_id || ''
  const token = query.token || ''
  const [estado, setEstado] = useState({ cargando: true, datos: null, error: null, codigo: null })

  useEffect(() => {
    let activo = true
    if (!sessionId) {
      setEstado({ cargando: false, datos: null, error: 'Falta el identificador de sesión de Stripe.', codigo: 400 })
      return () => { activo = false }
    }
    if (!token && !sesion.token) {
      setEstado({ cargando: false, datos: null, error: 'El enlace de confirmación requiere un token de verificación válido.', codigo: 403 })
      return () => { activo = false }
    }
    ;(async () => {
      try {
        const { data } = token
          ? await pagosApi.consultarRetornoPublico(sessionId, token)
          : await pagosApi.confirmarCheckout(sessionId)
        if (activo) setEstado({ cargando: false, datos: data, error: null, codigo: 200 })
      } catch (err) {
        if (activo) {
          setEstado({
            cargando: false,
            datos: null,
            error: apiErrorMessage(err),
            codigo: err?.response?.status || 500,
          })
        }
      }
    })()
    return () => { activo = false }
  }, [sessionId, token, sesion.token])

  const esVistaPublica = Boolean(token) || !sesion.usuario
  const accionVolver = () => (esVistaPublica
    ? <button type="button" className="btn btn-primario" onClick={() => go('/anuncios')}>Volver al sitio web</button>
    : <button type="button" className="btn btn-primario" onClick={() => go('/agenda')}>Volver a Agenda</button>)

  if (estado.cargando) {
    return (
      <div className="mx-auto w-full max-w-[920px] px-4 py-6">
        <CabeceraPagina titulo="Verificando operación con Stripe">Consultando el estado real directamente con Stripe Sandbox…</CabeceraPagina>
        <section className="hoja hoja-cuerpo"><Cargando filas={5} /></section>
      </div>
    )
  }

  if (estado.error || !estado.datos) {
    const tituloError = estado.codigo === 404
      ? 'Sesión inexistente'
      : estado.codigo === 401 || estado.codigo === 403
        ? 'Enlace no autorizado'
        : estado.codigo === 410
          ? 'Enlace caducado'
          : 'No se pudo verificar la operación'
    return (
      <div className="mx-auto w-full max-w-[920px] px-4 py-6">
        <CabeceraPagina titulo={tituloError}>La confirmación solo se valida directamente con Stripe desde el servidor.</CabeceraPagina>
        <section className="hoja hoja-cuerpo grid gap-4">
          <Aviso tipo="error">{estado.error || 'No se recibió información de confirmación desde el servidor.'}</Aviso>
          <div className="acciones justify-start">{accionVolver()}</div>
        </section>
      </div>
    )
  }

  const d = estado.datos
  const esSetup = d.tipo === 'setup'
  const confirmado = d.estado_interno === 'confirmado'
  const duplicado = d.estado_interno === 'reconciliacion_duplicada'
  const rechazado = d.estado_interno === 'rechazado'
  const expirado = d.estado_interno === 'expirado'
  const Icono = confirmado ? CheckCircle2 : (rechazado || expirado || duplicado) ? XCircle : Clock
  const monto = d.importe ?? d.monto ?? 0
  const referencia = d.referencia_pago || d.stripe_pago_intent || d.stripe_sesion || '—'

  return (
    <div className="mx-auto w-full max-w-[920px] px-4 py-6">
      <CabeceraPagina titulo={d.titulo || (esSetup ? 'Registro de tarjeta' : 'Resultado del pago')}>
        {esSetup
          ? 'Registro de tarjeta verificado mediante Stripe Sandbox.'
          : 'Resultado verificado directamente con Stripe Sandbox.'}
      </CabeceraPagina>

      <section className="hoja">
        <header className="hoja-titulo">
          <div className="flex items-center gap-3">
            <Icono size={28} className={confirmado ? 'text-acento-texto shrink-0' : 'text-tinta-suave shrink-0'} aria-hidden="true" />
            <div>
              <h2>
                {confirmado
                  ? (esSetup ? '¡Tarjeta registrada correctamente!' : '¡Pago confirmado por Stripe Sandbox!')
                  : (d.titulo || (esSetup ? 'Registro de tarjeta no completado' : 'Operación no completada'))}
              </h2>
              <p className="text-sm text-tinta-suave">
                {confirmado
                  ? (esSetup
                    ? 'No se ha realizado ningún cobro. La tarjeta quedó verificada en Stripe Sandbox.'
                    : 'La operación fue verificada en Stripe Sandbox (entorno de pruebas, sin cobro real).')
                  : d.detalle_error || (esSetup
                    ? 'El registro de la tarjeta aún no figura como completado en Stripe.'
                    : 'La operación aún no figura como pagada.')}
              </p>
            </div>
          </div>
          {esSetup ? (
            <Etiqueta estado={confirmado ? 'Activo' : expirado ? 'Inactivo' : 'Pendiente de pago'}>
              {confirmado ? 'Tarjeta registrada' : (expirado ? 'Expirado' : 'Pendiente')}
            </Etiqueta>
          ) : (
            <Etiqueta estado={confirmado ? 'Pago aprobado' : rechazado ? 'Pago rechazado' : 'Pendiente de pago'} />
          )}
        </header>

        <div className="hoja-cuerpo grid gap-5">
          {duplicado && (
            <Aviso tipo="error">
              <AlertTriangle size={16} className="inline mr-1" />
              Se detectó un pago adicional sobre una cuota que ya había sido liquidada. Contacte con UNEXO para su revisión.
            </Aviso>
          )}

          {!esVistaPublica && d.tipo === 'payment' && d.faltantes_conversion?.length > 0 && confirmado && (
            <Aviso>
              <strong>Pago confirmado por Stripe · Validación comercial pendiente:</strong> para completar la matrícula falta: {d.faltantes_conversion.join(' ')}
            </Aviso>
          )}

          {esSetup ? (
            <>
              <dl className="grid grid-cols-[repeat(auto-fit,minmax(180px,1fr))] gap-4">
                {!esVistaPublica && d.prospecto && <div><dt className="text-xs text-tinta-suave">Prospecto</dt><dd className="font-semibold">{d.prospecto}</dd></div>}
                <div><dt className="text-xs text-tinta-suave">Marca de la tarjeta</dt><dd className="font-semibold inline-flex items-center gap-1.5"><CreditCard size={15} aria-hidden="true" /> {d.marca_tarjeta || 'Pendiente'}</dd></div>
                <div><dt className="text-xs text-tinta-suave">Últimos 4 dígitos</dt><dd className="font-semibold tabular-nums">{d.ultimos_digitos ? `•••• ${d.ultimos_digitos}` : '—'}</dd></div>
                <div><dt className="text-xs text-tinta-suave">Fecha de vencimiento</dt><dd className="font-semibold tabular-nums">{d.vencimiento || '—'}</dd></div>
                <div><dt className="text-xs text-tinta-suave">Fecha de registro</dt><dd className="tabular-nums">{fecha(d.fecha_confirmacion, true)}</dd></div>
                <div><dt className="text-xs text-tinta-suave">Referencia Stripe</dt><dd className="font-mono text-xs break-all">{referencia}</dd></div>
              </dl>

              <p className="rounded-ui border border-filete bg-niebla-2 px-3 py-2.5 text-sm font-medium text-tinta">
                No se ha realizado ningún cobro. Tus datos de tarjeta se almacenan de forma segura en Stripe Sandbox.
              </p>
            </>
          ) : (
            <>
              <dl className="cifras">
                <div><dt>Importe ({d.moneda || 'BOB'})</dt><dd className="tabular-nums">{bs(monto)}</dd></div>
                <div><dt>Cuota</dt><dd className="tabular-nums">{d.nro_cuota} de {d.total_cuotas}</dd></div>
                <div><dt>Estado del pago</dt><dd>{confirmado ? 'Pago confirmado' : (d.estado_cuota || d.estado_interno)}</dd></div>
                {!esVistaPublica && <div><dt>Saldo pendiente</dt><dd className="tabular-nums">{bs(d.saldo_pendiente)}</dd></div>}
              </dl>

              <dl className="grid grid-cols-[repeat(auto-fit,minmax(210px,1fr))] gap-4 border-t border-filete pt-4">
                <div><dt className="text-xs text-tinta-suave">Programa educativo</dt><dd className="font-semibold">{d.programa || '—'}{d.modulo ? ` · ${d.modulo}` : ''}</dd></div>
                <div><dt className="text-xs text-tinta-suave">Moneda</dt><dd>{d.moneda || 'BOB'} (Bolivianos)</dd></div>
                <div><dt className="text-xs text-tinta-suave">Referencia de pago</dt><dd className="font-mono text-xs break-all">{referencia}</dd></div>
                <div><dt className="text-xs text-tinta-suave">Fecha y hora</dt><dd className="tabular-nums">{fecha(d.fecha_confirmacion, true)}</dd></div>
                {!esVistaPublica && d.prospecto && <div><dt className="text-xs text-tinta-suave">Prospecto</dt><dd className="font-semibold">{d.prospecto}</dd></div>}
                {!esVistaPublica && d.estado_comercial && <div><dt className="text-xs text-tinta-suave">Estado comercial</dt><dd>{d.estado_comercial}</dd></div>}
              </dl>

              <p className="rounded-ui border border-filete bg-niebla-2 px-3 py-2 text-xs text-tinta-suave">
                {d.aviso_sandbox || 'Operación de demostración mediante Stripe Sandbox (moneda BOB, sin movimiento real de dinero ni valor fiscal).'}
              </p>
            </>
          )}

          <div className="acciones justify-start flex-wrap">
            {esVistaPublica ? (
              <button type="button" className="btn btn-primario" onClick={() => go('/anuncios')}>Volver al sitio web</button>
            ) : (
              d.nro_tarjeta
                ? <button type="button" className="btn btn-primario" onClick={() => go(`/agenda?interes=${d.nro_tarjeta}`)}>Ver orden en Agenda</button>
                : <button type="button" className="btn btn-primario" onClick={() => go('/agenda')}>Volver a Agenda</button>
            )}
            {d.url_checkout && !confirmado && !expirado && (
              <button type="button" className="btn btn-acento" onClick={() => window.location.assign(d.url_checkout)}>
                {esSetup ? 'Completar registro en Stripe' : 'Completar pago en Stripe'}
              </button>
            )}
            {confirmado && !esSetup && (
              <button type="button" className="btn btn-secundario" onClick={() => window.print()}><Printer size={16} /> Imprimir comprobante</button>
            )}
            {!esVistaPublica && d.receipt_url && (
              <a className="btn btn-texto" href={d.receipt_url} target="_blank" rel="noreferrer"><ExternalLink size={16} /> Recibo de prueba Stripe</a>
            )}
          </div>
        </div>
      </section>
    </div>
  )
}

PPagoCuota.jsx.text:
import { useEffect, useState } from 'react'
import { CheckCircle2, ExternalLink, XCircle } from 'lucide-react'
import { Aviso, CabeceraPagina, Cargando, Etiqueta, bs, fecha } from '../componentes/ui'
import { apiErrorMessage } from '../servicios/errors'
import { go, useAppRoute } from '../servicios/navigation'
import * as pagosApi from '../api/pagos'

/**
 * CU6: enlace público seguro por cuota enviado por correo electrónico.
 * Verifica en tiempo real el estado en PostgreSQL, recupera o regenera la sesión de Stripe y redirige al cliente.
 */
export default function PPagoCuota() {
  const { query } = useAppRoute()
  const token = query.token || ''
  const [estado, setEstado] = useState({ cargando: true, datos: null, error: null })

  useEffect(() => {
    let activo = true
    if (!token) {
      setEstado({ cargando: false, datos: null, error: 'Falta el token de verificación de la cuota.' })
      return () => { activo = false }
    }
    ;(async () => {
      try {
        const { data } = await pagosApi.abrirEnlaceCuotaPublico(token)
        if (!activo) return
        setEstado({ cargando: false, datos: data, error: null })
        if (data.estado_link === 'pendiente' && data.url_checkout && !query.sin_redirigir) {
          window.location.assign(data.url_checkout)
        }
      } catch (err) {
        if (activo) {
          setEstado({ cargando: false, datos: null, error: apiErrorMessage(err) })
        }
      }
    })()
    return () => { activo = false }
  }, [token, query.sin_redirigir])

  if (estado.cargando) {
    return (
      <div className="mx-auto w-full max-w-[820px] px-4 py-6">
        <CabeceraPagina titulo="Preparando enlace seguro de pago">Verificando cuota pendiente en UNEXO y conectando con Stripe Sandbox…</CabeceraPagina>
        <section className="hoja hoja-cuerpo"><Cargando filas={4} /></section>
      </div>
    )
  }

  if (estado.error) {
    return (
      <div className="mx-auto w-full max-w-[820px] px-4 py-6">
        <CabeceraPagina titulo="Enlace no disponible">No se pudo iniciar la sesión de pago solicitada.</CabeceraPagina>
        <section className="hoja hoja-cuerpo grid gap-4">
          <Aviso tipo="error">{estado.error}</Aviso>
          <div className="acciones justify-start">
            <button type="button" className="btn btn-primario" onClick={() => go('/anuncios')}>Volver al catálogo</button>
          </div>
        </section>
      </div>
    )
  }

  const d = estado.datos
  const pagada = d.estado_link === 'pagada'
  const pendiente = d.estado_link === 'pendiente'
  const Icono = pagada ? CheckCircle2 : XCircle

  return (
    <div className="mx-auto w-full max-w-[820px] px-4 py-6">
      <CabeceraPagina titulo={pendiente ? 'Redirigiendo a Stripe Checkout' : pagada ? 'Cuota ya pagada' : 'Solicitud no disponible'}>
        {d.aviso_sandbox}
      </CabeceraPagina>

      <section className="hoja">
        <header className="hoja-titulo flex-wrap gap-2">
          <div className="flex items-center gap-3">
            {!pendiente && <Icono size={24} className={pagada ? 'text-acento-texto' : 'text-tinta-suave'} aria-hidden="true" />}
            <div>
              <h2>{d.programa}</h2>
              {d.modulo && <p className="text-sm text-tinta-suave">{d.modulo}</p>}
            </div>
          </div>
          <Etiqueta estado={pagada ? 'Pago aprobado' : pendiente ? 'Pendiente de pago' : 'Perdido'}>
            {pagada ? 'Pagada' : pendiente ? 'Pendiente de pago' : 'No disponible'}
          </Etiqueta>
        </header>

        <div className="hoja-cuerpo grid gap-4">
          <dl className="cifras">
            <div><dt>Importe ({d.moneda})</dt><dd className="tabular-nums">{bs(d.importe)}</dd></div>
            <div><dt>Cuota</dt><dd className="tabular-nums">{d.nro_cuota} de {d.total_cuotas}</dd></div>
            <div><dt>Vencimiento</dt><dd className="tabular-nums">{fecha(d.fecha_vencimiento)}</dd></div>
          </dl>

          {!pendiente && <Aviso tipo={pagada ? 'ok' : 'error'}>{d.mensaje}</Aviso>}

          <div className="acciones justify-start flex-wrap">
            {pendiente && d.url_checkout && (
              <button type="button" className="btn btn-primario" onClick={() => window.location.assign(d.url_checkout)}>
                <ExternalLink size={16} /> Ir a pagar en Stripe
              </button>
            )}
            <button type="button" className="btn btn-secundario" onClick={() => go('/anuncios')}>Volver al catálogo</button>
          </div>
        </div>
      </section>
    </div>
  )
}

PValidacionPagos.jsx.text:
import { useState } from 'react'
import { FileSearch, ReceiptText } from 'lucide-react'
import { go } from '../servicios/navigation'
import { Aviso, CabeceraPagina, Campo, Cargando, Etiqueta, Modal, Vacio, bs, fecha, useAviso, useDatos } from '../componentes/ui'
import * as pagosApi from '../api/pagos'

const ESTADOS = ['En revision', 'Pendiente de pago', 'Pago aprobado', 'Pago rechazado']
const TEXTO = { 'En revision': 'En revisión' }

function origenDeCuota(c) {
  if (c.proveedor === 'stripe' || c.stripe_pago_intent) return 'Stripe Sandbox'
  if (c.comprobantes?.length > 0 || c.estado === 'En revision') return 'QR / Transferencia'
  if (c.estado === 'Pago aprobado' || c.observacion?.includes('SIM-')) return 'Manual / histórico'
  return 'Pendiente de cobro'
}

/** CU6: coordinación revisa los comprobantes manuales de cada cuota; los cobros por Stripe muestran su referencia verificada. */
export default function PValidacionPagos() {
  const [estado, setEstado] = useState('En revision')
  const { datos, cargando, error, recargar } = useDatos(async () => (await pagosApi.cuotas({ estado: estado || undefined })).data.cuotas, [estado], { intervaloMs: 4000, refrescarAlEnfocar: true })
  const [revisar, setRevisar] = useState(null)
  const aviso = useAviso()

  return (
    <>
      <CabeceraPagina titulo="Validación de pagos">Revise los comprobantes manuales (QR/transferencia) y apruebe o rechace la cuota. Los pagos Stripe quedan verificados automáticamente.</CabeceraPagina>
      <div className="barra-filtros">
        <div className="segmentos" role="group" aria-label="Estado de la cuota">
          {ESTADOS.map((e) => <button key={e} type="button" aria-pressed={estado === e} onClick={() => setEstado(e)}>{TEXTO[e] || e}</button>)}
          <button type="button" aria-pressed={!estado} onClick={() => setEstado('')}>Todas</button>
        </div>
      </div>
      {error && <Aviso tipo="error">{error}</Aviso>}
      {cargando && !datos ? <Cargando /> : !datos?.length ? <Vacio titulo={estado === 'En revision' ? 'No hay comprobantes por revisar' : 'Sin cuotas en este estado'} icono={ReceiptText} /> : (
        <div className="tabla-marco">
          <table className="tabla">
            <thead><tr><th>Prospecto</th><th>Orden · cuota</th><th className="num">Monto</th><th>Origen</th><th>Vence</th><th>Vendedor</th><th>Estado</th><th /></tr></thead>
            <tbody>
              {datos.map((c) => (
                <tr key={`${c.nro_orden}-${c.nro_cuota}`}>
                  <td><a href="#" onClick={(e) => { e.preventDefault(); go(`/agenda?interes=${c.nro_tarjeta}`) }}><strong>{c.prospecto}</strong></a><br /><small>{c.modulo_nombre}</small></td>
                  <td className="tabular-nums">#{c.nro_orden} · {c.nro_cuota}</td>
                  <td className="num">{bs(c.monto)}</td>
                  <td>{origenDeCuota(c)}</td>
                  <td className="tabular-nums">{fecha(c.fecha_vencimiento)}</td>
                  <td>{c.vendedor}</td>
                  <td><Etiqueta estado={c.estado}>{TEXTO[c.estado] || c.estado}</Etiqueta></td>
                  <td>{(c.comprobantes.length > 0 || c.estado === 'En revision' || c.stripe_pago_intent) && <button type="button" className="btn btn-secundario" onClick={() => setRevisar(c)}><FileSearch size={16} /> {c.estado === 'En revision' && c.proveedor !== 'stripe' ? 'Revisar' : 'Ver'}</button>}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {revisar && <Revision cuota={revisar} onCerrar={() => setRevisar(null)} onListo={(m) => { aviso.ok(m); setRevisar(null); recargar() }} aviso={aviso} />}
      {aviso.nodo}
    </>
  )
}

function Revision({ cuota, onCerrar, onListo, aviso }) {
  const comp = cuota.comprobantes[0]
  const archivo = useDatos(async () => (comp ? (await pagosApi.comprobante(comp.nro_comprobante)).data.comprobante : null), [comp?.nro_comprobante])
  const [observacion, setObservacion] = useState('')
  const esStripe = cuota.proveedor === 'stripe'
  const enRevision = cuota.estado === 'En revision' && !esStripe
  async function decidir(accion) {
    try {
      const { data } = await pagosApi[accion](cuota.nro_orden, cuota.nro_cuota, observacion || undefined)
      onListo(data.faltantes_conversion?.length ? `${data.mensaje} Para matricular falta: ${data.faltantes_conversion.join(' ')}` : data.mensaje)
    } catch (e) { aviso.error(e) }
  }
  const a = archivo.datos
  return (
    <Modal ancho titulo={`${cuota.prospecto} · cuota ${cuota.nro_cuota} de la orden #${cuota.nro_orden}`} descripcion={comp ? `${bs(cuota.monto)} · ${comp.nombre_archivo || 'comprobante'} · enviado ${fecha(comp.fecha_envio, true)}` : esStripe ? `${bs(cuota.monto)} · Stripe Sandbox (${cuota.moneda || 'BOB'})` : `${bs(cuota.monto)} · registro histórico de pasarela anterior`} onCerrar={onCerrar}
      pie={enRevision && <div className="acciones"><button type="button" className="btn btn-peligro-suave" disabled={!observacion.trim()} onClick={() => decidir('rechazar')}>Rechazar</button><button type="button" className="btn btn-primario" onClick={() => decidir('aprobar')}>Aprobar pago</button></div>}>
      {archivo.cargando ? <Cargando filas={3} /> : a?.mime === 'application/pdf'
        ? <iframe title="Comprobante" src={a.archivo} className="h-[480px] w-full rounded-ui border border-filete" />
        : a && <img src={a.archivo} alt={`Comprobante de ${cuota.prospecto}`} className="mx-auto max-h-[480px] rounded-ui border border-filete" />}
      {esStripe && <p><b>Referencia Stripe:</b> <span className="font-mono text-xs">{cuota.stripe_pago_intent || cuota.stripe_sesion}</span></p>}
      {!comp && cuota.observacion && <p><b>Detalle:</b> {cuota.observacion}</p>}
      {comp?.remitente && <p><b>Enviado por:</b> {comp.remitente}{comp.hora_pago ? ` · pagado el ${fecha(comp.hora_pago, true)}` : ''}</p>}
      {comp?.observacion && <p><b>Observación:</b> {comp.observacion}</p>}
      {enRevision && <Campo etiqueta="Observación" ayuda="Obligatoria para rechazar: el vendedor la verá en la ficha."><textarea value={observacion} maxLength={1000} onChange={(e) => setObservacion(e.target.value)} /></Campo>}
    </Modal>
  )
}

PlanPagos.jsx.text:
import { useState } from 'react'
import { Ban, CheckCircle2, ExternalLink, Info, Plus, Send } from 'lucide-react'
import { Aviso, Boton, Campo, Etiqueta, Modal, fecha } from '../ui'
import { apiErrorMessage } from '../../servicios/errors'
import { bsPago } from './ResumenPagos'
import * as pagosApi from '../../api/pagos'

/** Sección 2: Órdenes activas como elemento principal, cuotas limpias y órdenes liquidadas/anuladas contraídas. */
export default function PlanPagos({ t, ordenes, editable, puedeGenerar, onGenerar, onEnviarCuota, aviso, onCambio }) {
  const [detalleOrden, setDetalleOrden] = useState(null)
  const [detalleCuota, setDetalleCuota] = useState(null)
  const [anularOrdenModal, setAnularOrdenModal] = useState(null)

  const ordenesActivas = ordenes.filter((o) => {
    if (o.estado === 'Anulada') return false
    const total = o.cuotas.length
    const pagadas = o.cuotas.filter((c) => c.estado === 'Pago aprobado').length
    return !(total > 0 && pagadas === total)
  })
  const ordenesCerradas = ordenes.filter((o) => !ordenesActivas.includes(o))

  if (!ordenes.length || (!ordenesActivas.length && !ordenesCerradas.length)) {
    return (
      <section className="hoja hoja-cuerpo grid justify-items-start gap-2.5">
        <h4>Sin órdenes de pago</h4>
        <p className="text-sm text-tinta-suave">Configura los módulos, descuentos y condiciones comerciales para generar una orden.</p>
        {puedeGenerar && (
          <button type="button" className="btn btn-primario" onClick={onGenerar}>
            <Plus size={16} /> Generar orden de pago
          </button>
        )}
      </section>
    )
  }

  return (
    <section className="grid gap-4">
      {!ordenesActivas.length && (
        <div className="hoja hoja-cuerpo flex flex-wrap items-center justify-between gap-3">
          <div>
            <h4>Sin órdenes pendientes activas</h4>
            <p className="text-sm text-tinta-suave">Las órdenes anteriores ya fueron liquidadas o anuladas.</p>
          </div>
          {puedeGenerar && (
            <button type="button" className="btn btn-primario" onClick={onGenerar}>
              <Plus size={16} /> Generar orden de pago
            </button>
          )}
        </div>
      )}

      {ordenesActivas.map((o) => (
        <TarjetaOrden
          key={o.nro_orden}
          o={o}
          t={t}
          editable={editable}
          onVerDetalles={() => setDetalleOrden(o)}
          onEnviarCuota={(c) => onEnviarCuota(o, c)}
          onVerCuota={(c) => setDetalleCuota({ orden: o, cuota: c })}
        />
      ))}

      {ordenesCerradas.length > 0 && (
        <details className="hoja">
          <summary className="hoja-titulo cursor-pointer list-none select-none">
            <span className="font-semibold">Órdenes liquidadas y anuladas ({ordenesCerradas.length})</span>
            <span className="text-xs text-tinta-suave">Desplegar</span>
          </summary>
          <div className="hoja-cuerpo grid gap-4">
            {ordenesCerradas.map((o) => (
              <TarjetaOrden
                key={o.nro_orden}
                o={o}
                t={t}
                editable={editable}
                onVerDetalles={() => setDetalleOrden(o)}
                onEnviarCuota={(c) => onEnviarCuota(o, c)}
                onVerCuota={(c) => setDetalleCuota({ orden: o, cuota: c })}
              />
            ))}
          </div>
        </details>
      )}

      {detalleOrden && (
        <ModalDetallesOrden
          orden={detalleOrden}
          editable={editable}
          onCerrar={() => setDetalleOrden(null)}
          onAnular={(o) => { setDetalleOrden(null); setAnularOrdenModal(o) }}
        />
      )}

      {detalleCuota && (
        <ModalDetalleCuota
          orden={detalleCuota.orden}
          cuota={detalleCuota.cuota}
          onCerrar={() => setDetalleCuota(null)}
        />
      )}

      {anularOrdenModal && (
        <ModalAnularOrden
          orden={anularOrdenModal}
          onCerrar={() => setAnularOrdenModal(null)}
          onListo={(m) => { aviso.ok(m); setAnularOrdenModal(null); onCambio() }}
        />
      )}
    </section>
  )
}

function TarjetaOrden({ o, t, editable, onVerDetalles, onEnviarCuota, onVerCuota }) {
  const anulada = o.estado === 'Anulada'
  const totalCuotas = o.cuotas.length
  const pagadas = o.cuotas.filter((c) => c.estado === 'Pago aprobado').length
  const liquidada = !anulada && totalCuotas > 0 && pagadas === totalCuotas
  const programa = o.items?.[0]?.programa_nombre || t.programa_nombre

  return (
    <article className="hoja">
      <header className="hoja-titulo flex-wrap gap-3">
        <div>
          <h4>Orden de pago #{o.nro_orden} · {programa}</h4>
          <p className="text-sm text-tinta-suave">
            {o.items.length} {o.items.length === 1 ? 'módulo contratado' : 'módulos contratados'}
            {' · '}Total: <b className="text-tinta tabular-nums">{bsPago(o.total)}</b>
          </p>
        </div>
        <div className="acciones flex-wrap">
          {anulada
            ? <Etiqueta estado="Perdido">Anulada</Etiqueta>
            : <Etiqueta estado={liquidada ? 'Pago aprobado' : 'Pendiente de pago'}>{liquidada ? 'Liquidada' : 'Activa'}</Etiqueta>}
          <button type="button" className="btn btn-secundario" onClick={onVerDetalles}>
            <Info size={15} /> Detalles y opciones
          </button>
        </div>
      </header>

      {anulada && o.motivo_anulacion && (
        <div className="px-6 pt-3"><Aviso tipo="error">Orden anulada: {o.motivo_anulacion}</Aviso></div>
      )}

      <div className="hoja-cuerpo grid gap-2.5">
        {o.cuotas.map((c) => {
          const pagada = c.estado === 'Pago aprobado'
          const puedeEnviar = editable && !anulada && ['Pendiente de pago', 'Pago rechazado'].includes(c.estado)
          return (
            <div key={c.nro_cuota} className="flex flex-wrap items-center justify-between gap-3 rounded-ui border border-filete px-4 py-3">
              <div className="grid gap-0.5">
                <strong className="text-sm">Cuota {c.nro_cuota} de {totalCuotas}</strong>
                <div className="text-xs text-tinta-suave">
                  Vencimiento: <span className="tabular-nums">{fecha(c.fecha_vencimiento)}</span>
                </div>
                <div className="mt-0.5 flex flex-wrap items-center gap-2.5">
                  <strong className="text-base tabular-nums">{bsPago(c.monto)}</strong>
                  <Etiqueta estado={c.estado}>{pagada ? 'Pago confirmado' : c.estado}</Etiqueta>
                </div>
              </div>

              <div className="acciones">
                {puedeEnviar && (
                  <button type="button" className="btn btn-primario" onClick={() => onEnviarCuota(c)}>
                    <Send size={15} /> Enviar solicitud de pago
                  </button>
                )}
                {pagada && (
                  <button type="button" className="btn btn-secundario" onClick={() => onVerCuota(c)}>
                    <CheckCircle2 size={15} /> Ver detalles
                  </button>
                )}
              </div>
            </div>
          )
        })}
      </div>
    </article>
  )
}

function ModalDetallesOrden({ orden, editable, onCerrar, onAnular }) {
  const anulada = orden.estado === 'Anulada'
  const anulable = editable && !anulada && !orden.cuotas.some((c) => ['Pago aprobado', 'En revision'].includes(c.estado))

  return (
    <Modal ancho titulo={`Detalles de orden #${orden.nro_orden}`} descripcion={`Generada el ${fecha(orden.fecha_generacion, true)}`} onCerrar={onCerrar}>
      <div className="grid gap-4">
        <section className="grid gap-1.5">
          <strong className="text-sm">Módulos contratados</strong>
          <ul className="grid gap-1 rounded-ui border border-filete p-3 text-sm">
            {orden.items.map((i) => (
              <li key={i.nro_solicitud} className="flex justify-between gap-2">
                <span>{i.modulo_nombre}</span>
                <b className="tabular-nums">{bsPago(i.precio_acordado)}</b>
              </li>
            ))}
          </ul>
        </section>

        <section className="grid gap-1.5 text-sm">
          <div className="flex justify-between"><span>Subtotal</span><span className="tabular-nums">{bsPago(orden.subtotal)}</span></div>
          <div className="flex justify-between">
            <span>Descuentos ({orden.descuentos?.length ? orden.descuentos.map((d) => `${d.descuento?.nombre || d.descuento_codigo} (${Number(d.porcentaje)}%)`).join(', ') : 'Sin descuentos'})</span>
            <span className="tabular-nums text-exito">- {bsPago(orden.descuento_total)}</span>
          </div>
          <div className="flex justify-between font-bold border-t border-filete pt-2">
            <span>Total</span><span className="tabular-nums">{bsPago(orden.total)}</span>
          </div>
        </section>

        <div className="acciones justify-between flex-wrap">
          {anulable ? (
            <button type="button" className="btn btn-peligro-suave" onClick={() => onAnular(orden)}>
              <Ban size={15} /> Anular orden
            </button>
          ) : <span />}
          <button type="button" className="btn btn-primario" onClick={onCerrar}>Cerrar</button>
        </div>
      </div>
    </Modal>
  )
}

function ModalDetalleCuota({ orden, cuota, onCerrar }) {
  const metodoTxt = cuota.metodo
    ? (cuota.metodo.tipo === 'Tarjeta' ? `${cuota.metodo.marca} terminada en ${cuota.metodo.ultimos_digitos}` : cuota.metodo.tipo)
    : cuota.proveedor === 'stripe' ? 'Tarjeta en Stripe Sandbox' : 'Registro histórico'

  return (
    <Modal titulo={`Detalle · Cuota ${cuota.nro_cuota} (Orden #${orden.nro_orden})`} onCerrar={onCerrar}>
      <dl className="grid grid-cols-2 gap-3 text-sm max-movil:grid-cols-1">
        <div><dt className="text-xs text-tinta-suave">Importe</dt><dd className="font-bold tabular-nums">{bsPago(cuota.monto)} (BOB)</dd></div>
        <div><dt className="text-xs text-tinta-suave">Estado</dt><dd><Etiqueta estado={cuota.estado} /></dd></div>
        <div><dt className="text-xs text-tinta-suave">Fecha de pago</dt><dd className="tabular-nums">{fecha(cuota.fecha_pago, true)}</dd></div>
        <div><dt className="text-xs text-tinta-suave">Método</dt><dd>{metodoTxt}</dd></div>
        <div><dt className="text-xs text-tinta-suave">Pasarela</dt><dd>{cuota.proveedor === 'stripe' ? 'Stripe Checkout Sandbox' : 'Pago manual histórico'}</dd></div>
        {cuota.stripe_pago_intent && (
          <div className="col-span-full"><dt className="text-xs text-tinta-suave">Referencia Stripe</dt><dd className="font-mono text-xs break-all">{cuota.stripe_pago_intent}</dd></div>
        )}
        {!cuota.stripe_pago_intent && cuota.observacion && (
          <div className="col-span-full"><dt className="text-xs text-tinta-suave">Observación</dt><dd>{cuota.observacion}</dd></div>
        )}
      </dl>
      <div className="acciones justify-start">
        {cuota.stripe_recibo_url && (
          <a className="btn btn-secundario" href={cuota.stripe_recibo_url} target="_blank" rel="noreferrer"><ExternalLink size={15} /> Recibo Stripe</a>
        )}
        <button type="button" className="btn btn-primario" onClick={onCerrar}>Cerrar</button>
      </div>
    </Modal>
  )
}

function ModalAnularOrden({ orden, onCerrar, onListo }) {
  const [motivo, setMotivo] = useState('')
  const [error, setError] = useState(null)
  const [enviando, setEnviando] = useState(false)

  async function enviar(e) {
    e.preventDefault()
    setEnviando(true)
    try {
      onListo((await pagosApi.anularOrden(orden.nro_orden, motivo)).data.mensaje)
    } catch (err) {
      setError(apiErrorMessage(err))
      setEnviando(false)
    }
  }

  return (
    <Modal titulo={`Anular orden #${orden.nro_orden}`} descripcion={`Importe: ${bsPago(orden.total)}. Si tiene enlaces Stripe pendientes, quedarán deshabilitados.`} onCerrar={onCerrar}>
      <form className="grid gap-4" onSubmit={enviar}>
        <Campo etiqueta="Motivo de anulación" requerido ayuda="Mínimo 5 caracteres. Queda registrado en el historial.">
          <textarea required minLength={5} maxLength={500} value={motivo} onChange={(e) => setMotivo(e.target.value)} />
        </Campo>
        <Aviso tipo="error">{error}</Aviso>
        <div className="acciones">
          <button type="button" className="btn btn-secundario" onClick={onCerrar}>Cancelar</button>
          <Boton type="submit" className="btn-peligro-suave" cargando={enviando} disabled={motivo.trim().length < 5}>Confirmar anulación</Boton>
        </div>
      </form>
    </Modal>
  )
}

