import { useState } from 'react'
import { BadgeDollarSign } from 'lucide-react'
import { puede, useAuth } from '../servicios/auth'
import { Aviso, CabeceraPagina, Campo, Cargando, Etiqueta, Vacio, bs, fecha, nombre, useAviso, useDatos } from '../componentes/ui'
import * as seguimientoApi from '../api/seguimiento'

/** CU8: ventas concretadas y comisiones de cada vendedor; coordinación fija el porcentaje y registra los pagos. */
export default function PComisiones() {
  const sesion = useAuth()
  const gestiona = puede('seguimiento', 'modificacion', sesion)
  const comisiones = useDatos(async () => (await seguimientoApi.comisiones()).data, [], { intervaloMs: 5000, refrescarAlEnfocar: true })
  const resumen = useDatos(async () => (gestiona ? (await seguimientoApi.resumenComisiones()).data.vendedores : []), [gestiona], { intervaloMs: 5000, refrescarAlEnfocar: true })
  const [porcentaje, setPorcentaje] = useState('')
  const aviso = useAviso()
  const recargar = () => { comisiones.recargar(); resumen.recargar() }

  if (comisiones.cargando && !comisiones.datos) return <Cargando />
  if (comisiones.error) return <Aviso tipo="error">{comisiones.error}</Aviso>
  const lista = comisiones.datos.comisiones
  const pendiente = lista.filter((c) => c.estado === 'Pendiente').reduce((s, c) => s + Number(c.monto), 0)

  return (
    <>
      <CabeceraPagina titulo="Ventas y comisiones">Cada módulo matriculado genera la comisión del vendedor que hizo la venta, con el porcentaje vigente en ese momento.</CabeceraPagina>
      <dl className="cifras mb-6">
        <div><dt>Ventas concretadas</dt><dd>{lista.length}</dd></div>
        <div><dt>Comisión pendiente</dt><dd className="tabular-nums">{bs(pendiente)}</dd></div>
        <div><dt>Porcentaje vigente</dt><dd>{Number(comisiones.datos.porcentaje)}%</dd></div>
      </dl>
      {gestiona && (
        <div className="grid grid-cols-[minmax(0,2fr)_minmax(0,1fr)] gap-6 max-movil:grid-cols-1 mb-6">
          <section className="hoja"><header className="hoja-titulo"><h3>Por vendedor</h3></header>
            <div className="tabla-marco rounded-none border-0"><table className="tabla">
              <thead><tr><th>Vendedor</th><th className="num">Cursos</th><th className="num">Total</th><th className="num">Pendiente</th><th /></tr></thead>
              <tbody>{(resumen.datos || []).map((v) => (
                <tr key={v.correo}><td>{nombre(v)}</td><td className="num">{v.cursos_vendidos}</td><td className="num">{bs(v.comision_total)}</td><td className="num">{bs(v.comision_pendiente)}</td>
                  <td>{Number(v.comision_pendiente)> 0 && <button type="button" className="btn btn-secundario" onClick={async () => { try { aviso.ok((await seguimientoApi.pagarComisiones(v.correo)).data.mensaje); recargar() } catch (e) { aviso.error(e) } }}>Registrar pago</button>}</td></tr>
              ))}</tbody>
            </table></div>
          </section>
          {sesion.usuario?.rol === 'administrador' && <form className="hoja hoja-cuerpo grid gap-4" onSubmit={async (e) => { e.preventDefault(); try { aviso.ok((await seguimientoApi.actualizarConfiguracionComision(porcentaje)).data.mensaje); setPorcentaje(''); recargar() } catch (err) { aviso.error(err) } }}>
            <h3>Porcentaje de comisión</h3>
            <p className="text-sm text-tinta-suave">Se aplica a las ventas que se matriculen desde ahora.</p>
            <Campo etiqueta="Nuevo porcentaje (0 a 50)" requerido><input type="number" min={0} max={50} step="0.5" required value={porcentaje} onChange={(e) => setPorcentaje(e.target.value)} /></Campo>
            <div className="acciones"><button type="submit" className="btn btn-primario">Guardar</button></div>
          </form>}
        </div>
      )}
      {!lista.length ? <Vacio titulo="Todavía no hay ventas concretadas" icono={BadgeDollarSign} /> : (
        <div className="tabla-marco"><table className="tabla">
          <thead><tr><th>Alumno</th><th>Módulo</th><th>Vendedor</th><th className="num">%</th><th className="num">Comisión</th><th>Estado</th><th>Fecha</th></tr></thead>
          <tbody>{lista.map((c) => (
            <tr key={c.nro_solicitud}><td>{nombre(c.venta?.orden_pago?.interes?.prospecto)}</td><td>{c.venta?.modulo_nombre}</td><td>{nombre(c.vendedor)}</td>
              <td className="num">{Number(c.porcentaje)}</td><td className="num">{bs(c.monto)}</td><td><Etiqueta estado={c.estado} /></td><td className="tabular-nums">{fecha(c.created_at)}</td></tr>
          ))}</tbody>
        </table></div>
      )}
      {aviso.nodo}
    </>
  )
}

PMiDia.jsx.text:
import { useMemo, useState } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { go } from '../servicios/navigation'
import { useAuth } from '../servicios/auth'
import { Aviso, CabeceraPagina, Cargando, Etiqueta, Modal, Campo, bs, fecha, hora, nombre, useAviso, useDatos, HISTORIAL } from '../componentes/ui'
import * as reportesApi from '../api/reportes'
import * as seguimientoApi from '../api/seguimiento'

const DIAS = ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom']
const clave = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`

/** Inicio del vendedor: su resumen y la agenda del mes (RF4.3), con acceso directo a cada ficha. */
export default function PMiDia() {
  const { usuario } = useAuth()
  const [mes, setMes] = useState(() => { const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), 1) })
  const [dia, setDia] = useState(clave(new Date()))
  const [completar, setCompletar] = useState(null)
  const aviso = useAviso()
  const stats = useDatos(async () => (await reportesApi.estadisticasVendedor()).data.estadisticas, [], { intervaloMs: 5000, refrescarAlEnfocar: true })
  const celdas = useMemo(() => {
    const inicio = new Date(mes)
    inicio.setDate(1 - ((mes.getDay() + 6) % 7))
    return Array.from({ length: 42 }, (_, i) => new Date(inicio.getFullYear(), inicio.getMonth(), inicio.getDate() + i))
  }, [mes])
  const agenda = useDatos(async () => (await seguimientoApi.recordatorios({ desde: clave(celdas[0]), hasta: clave(celdas[41]) })).data.recordatorios, [celdas], { intervaloMs: 5000, refrescarAlEnfocar: true })
  const porDia = useMemo(() => (agenda.datos || []).reduce((g, r) => {
    const k = clave(new Date(r.fecha_programada))
    return { ...g, [k]: [...(g[k] || []), r] }
  }, {}), [agenda.datos])
  const hoy = clave(new Date())
  const s = stats.datos

  return (
    <>
      <CabeceraPagina titulo={`Buen día, ${usuario?.nombre}`}>Sus actividades agendadas y el estado de su cartera.</CabeceraPagina>
      {s ? (
        <dl className="cifras mb-6">
          <div><dt>Tarjetas abiertas</dt><dd>{s.abiertas}<small> de {s.tarjetas}</small></dd></div>
          <div><dt>Convertidos</dt><dd>{s.convertidos}</dd></div>
          <div><dt>Actividades pendientes</dt><dd>{s.actividades_pendientes}</dd></div>
          <div><dt>Contactos este mes</dt><dd>{s.interacciones_mes}</dd></div>
          <div><dt>Comisión por cobrar</dt><dd className="tabular-nums">{bs(s.comision_pendiente)}</dd></div>
        </dl>
      ) : <Cargando filas={1} />}
      <div className="grid grid-cols-[minmax(0,3fr)_minmax(0,2fr)] gap-6 max-movil:grid-cols-1">
        <section className="hoja">
          <header className="hoja-titulo">
            <h3 className="capitalize">{mes.toLocaleDateString('es-BO', { month: 'long', year: 'numeric' })}</h3>
            <div className="acciones">
              <button type="button" className="btn btn-texto btn-icono" aria-label="Mes anterior" onClick={() => setMes(new Date(mes.getFullYear(), mes.getMonth() - 1, 1))}><ChevronLeft size={18} /></button>
              <button type="button" className="btn btn-secundario" onClick={() => { const d = new Date(); setMes(new Date(d.getFullYear(), d.getMonth(), 1)); setDia(hoy) }}>Hoy</button>
              <button type="button" className="btn btn-texto btn-icono" aria-label="Mes siguiente" onClick={() => setMes(new Date(mes.getFullYear(), mes.getMonth() + 1, 1))}><ChevronRight size={18} /></button>
            </div>
          </header>
          <div className="hoja-cuerpo">
            <div className="grid grid-cols-7 overflow-hidden rounded-hoja border border-filete bg-papel">
              {DIAS.map((d) => <div key={d} className="border-b border-filete bg-niebla-2 p-2 text-center text-xs font-bold text-tinta-suave">{d}</div>)}
              {celdas.map((d) => {
                const k = clave(d)
                const items = porDia[k] || []
                return (
                  <button key={k} type="button" className={`grid min-h-[76px] content-start gap-1 border-r border-b border-filete px-2 py-1.5 text-left nth-[7n]:border-r-0 aria-pressed:shadow-[inset_0_0_0_2px_var(--acento)] max-movil:min-h-[52px] ${d.getMonth() !== mes.getMonth() ? 'bg-niebla-2 text-tinta-suave' : 'bg-papel'}`} aria-pressed={k === dia} aria-label={`${d.toLocaleDateString('es-BO')}: ${items.length} actividades`} onClick={() => setDia(k)}>
                    <span className={`grid size-[26px] place-items-center text-sm font-bold tabular-nums ${k === hoy ? 'rounded-full bg-navy text-white dark:bg-acento dark:text-sobre-acento' : ''}`}>{d.getDate()}</span>
                    <span className="flex flex-wrap gap-[3px]">{items.slice(0, 6).map((r) => <i key={r.nro_recordatorio} className={`size-2 rounded-full ${r.estado === 'Atrasada' ? 'bg-aviso' : 'bg-acento'}`} />)}</span>
                  </button>
                )
              })}
            </div>
          </div>
        </section>
        <section className="hoja">
          <header className="hoja-titulo"><h3>{new Date(`${dia}T12:00:00`).toLocaleDateString('es-BO', { weekday: 'long', day: 'numeric', month: 'long' })}</h3></header>
          <div className="hoja-cuerpo">
            {agenda.error && <Aviso tipo="error">{agenda.error}</Aviso>}
            {!(porDia[dia] || []).length ? <p className="text-tinta-suave">Sin actividades este día.</p> : (
              <ol className={HISTORIAL.lista}>
                {porDia[dia].map((r) => (
                  <li key={r.nro_recordatorio} className={HISTORIAL.item}>
                    <span className={HISTORIAL.tipo}>{hora(r.fecha_programada)} · <Etiqueta estado={r.estado} /></span>
                    <p className={HISTORIAL.texto}><a href="#" onClick={(e) => { e.preventDefault(); go(`/agenda?interes=${r.nro_tarjeta}`) }}>{nombre(r.interes?.prospecto)}</a>: {r.descripcion}</p>
                    {['Pendiente', 'Atrasada'].includes(r.estado) && <small className={HISTORIAL.nota}><button type="button" className="btn btn-texto" onClick={() => setCompletar({ r, resultado: '' })}>Marcar realizada</button></small>}
                  </li>
                ))}
              </ol>
            )}
          </div>
        </section>
      </div>
      {completar && (
        <Modal titulo="Marcar actividad como realizada" descripcion={completar.r.descripcion} onCerrar={() => setCompletar(null)}
          pie={<div className="acciones"><button type="button" className="btn btn-secundario" onClick={() => setCompletar(null)}>Cancelar</button><button type="button" className="btn btn-primario" disabled={completar.resultado.trim().length < 3} onClick={async () => {
            try { aviso.ok((await seguimientoApi.completarRecordatorio(completar.r.nro_recordatorio, completar.resultado)).data.mensaje); setCompletar(null); agenda.recargar(); stats.recargar() } catch (e) { aviso.error(e) }
          }}>Guardar</button></div>}>
          {new Date(completar.r.fecha_programada)> new Date() && <Aviso>Estaba agendada para el {fecha(completar.r.fecha_programada, true)}. ¿Está seguro de que ya se realizó?</Aviso>}
          <Campo etiqueta="Resultado" requerido><textarea value={completar.resultado} onChange={(e) => setCompletar({ ...completar, resultado: e.target.value })} /></Campo>
        </Modal>
      )}
      {aviso.nodo}
    </>
  )
}

PReportes.jsx.text:
import { useState } from 'react'
import { Download } from 'lucide-react'
import { descargarCsv } from '../servicios/archivos'
import { useAuth } from '../servicios/auth'
import { Aviso, Barras, CabeceraPagina, Campo, Cargando, Vacio, bs, nombre, useDatos } from '../componentes/ui'
import * as reportesApi from '../api/reportes'
import * as usuariosApi from '../api/usuarios'
import { ETAPA } from '../componentes/tonos'

const TIPOS = { tarjetas: 'Embudo de ventas', pagos: 'Cuotas y pagos', matriculas: 'Matrículas', comisiones: 'Comisiones', perdidas: 'Pérdidas y motivos', vendedores: 'Cartera por vendedor' }
const MONEDA = ['monto', 'precio']

/** CU8. Docente: "reporte es un listado, estadística es la representación porcentual". Aquí están los dos. */
export default function PReportes() {
  const { usuario } = useAuth()
  const [vista, setVista] = useState('estadisticas')
  const [f, setF] = useState({ tipo: 'tarjetas', desde: '', hasta: '', vendedor: '', estado: '', buscar: '' })
  const params = Object.fromEntries(Object.entries(f).filter(([, v]) => v))
  const est = useDatos(async () => (await reportesApi.estadisticas(params)).data, [f.desde, f.hasta, f.vendedor])
  const rep = useDatos(async () => (vista === 'listado' ? (await reportesApi.listado(params)).data : null), [vista, f.tipo, f.desde, f.hasta, f.vendedor, f.estado, f.buscar])
  const vendedores = useDatos(async () => (usuario?.rol === 'vendedor' ? [] : (await usuariosApi.vendedores()).data.vendedores), [usuario?.rol])
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value })

  return (
    <>
      <CabeceraPagina titulo="Reportes y estadísticas">{usuario?.rol === 'vendedor' ? 'Sus cifras.' : 'Filtre por fechas y vendedor para ver cuántos leads tiene cada uno y cuántos concretó.'}</CabeceraPagina>
      <div className="pestanas mb-4" role="tablist">
        <button type="button" role="tab" aria-selected={vista === 'estadisticas'} onClick={() => setVista('estadisticas')}>Estadísticas (%)</button>
        <button type="button" role="tab" aria-selected={vista === 'listado'} onClick={() => setVista('listado')}>Reportes (listados)</button>
      </div>
      <div className="barra-filtros">
        {vista === 'listado' && <Campo etiqueta="Reporte"><select value={f.tipo} onChange={set('tipo')}>{Object.entries(TIPOS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></Campo>}
        <Campo etiqueta="Desde"><input type="date" value={f.desde} onChange={set('desde')} /></Campo>
        <Campo etiqueta="Hasta"><input type="date" value={f.hasta} min={f.desde || undefined} onChange={set('hasta')} /></Campo>
        {usuario?.rol !== 'vendedor' && <Campo etiqueta="Vendedor"><select value={f.vendedor} onChange={set('vendedor')}><option value="">Todos</option>{(vendedores.datos || []).map((v) => <option key={v.correo} value={v.correo}>{nombre(v)}</option>)}</select></Campo>}
        {vista === 'listado' && <Campo etiqueta="Buscar"><input type="search" value={f.buscar} onChange={set('buscar')} placeholder="Prospecto, CI o módulo" /></Campo>}
      </div>

      {vista === 'estadisticas' && (est.error ? <Aviso tipo="error">{est.error}</Aviso> : est.cargando && !est.datos ? <Cargando /> : (
        <>
          <div className="grid grid-cols-2 gap-6 max-movil:grid-cols-1 mb-6">
            <section className="hoja"><header className="hoja-titulo"><h3>Embudo por etapa</h3></header><div className="hoja-cuerpo"><Barras datos={est.datos.embudo.map((e) => ({ ...e, tono: ETAPA[e.etiqueta] }))} /></div></section>
            <section className="hoja"><header className="hoja-titulo"><h3>Origen de los leads</h3></header><div className="hoja-cuerpo"><Barras datos={est.datos.origen_de_leads} tono="seguimiento" /></div></section>
          </div>
          <div className="grid grid-cols-2 gap-6 max-movil:grid-cols-1 mb-6">
            <section className="hoja"><header className="hoja-titulo"><h3>Pérdidas por categoría (CU5)</h3></header><div className="hoja-cuerpo"><Barras datos={est.datos.perdidas_por_categoria} tono="perdido" /></div></section>
            <section className="hoja"><header className="hoja-titulo"><h3>Pérdidas por motivo</h3></header><div className="hoja-cuerpo"><Barras datos={est.datos.perdidas_por_motivo} tono="perdido" /></div></section>
          </div>
          <section className="hoja"><header className="hoja-titulo"><h3>Conversión por vendedor</h3></header>
            {!est.datos.conversion_por_vendedor.length ? <Vacio titulo="Sin datos de vendedores" /> : (
              <div className="tabla-marco rounded-none border-0"><table className="tabla"><thead><tr><th>Vendedor</th><th className="num">Tarjetas</th><th className="num">Concretadas</th><th className="num">Perdidas</th><th className="num">Conversión</th></tr></thead>
                <tbody>{est.datos.conversion_por_vendedor.map((v) => <tr key={v.vendedor}><td>{v.vendedor}</td><td className="num">{v.total}</td><td className="num">{v.convertidos}</td><td className="num">{v.perdidos}</td><td className="num">{Number(v.tasa_conversion).toLocaleString('es-BO')} %</td></tr>)}</tbody></table></div>
            )}
          </section>
        </>
      ))}

      {vista === 'listado' && (rep.error ? <Aviso tipo="error">{rep.error}</Aviso> : rep.cargando && !rep.datos ? <Cargando /> : rep.datos && (
        <section className="hoja">
          <header className="hoja-titulo"><h3>{rep.datos.titulo} · {rep.datos.filas.length} fila(s)</h3>
            <button type="button" className="btn btn-secundario" disabled={!rep.datos.filas.length} onClick={() => descargarCsv(`reporte_${f.tipo}.csv`, rep.datos.filas)}><Download size={16} /> Exportar CSV</button></header>
          {!rep.datos.filas.length ? <Vacio titulo="Sin resultados con esos filtros" /> : (
            <div className="tabla-marco rounded-none border-0"><table className="tabla">
              <thead><tr>{rep.datos.columnas.map((c) => <th key={c.key} className={MONEDA.includes(c.key) ? 'num' : ''}>{c.label}</th>)}</tr></thead>
              <tbody>{rep.datos.filas.map((fila, i) => <tr key={i}>{rep.datos.columnas.map((c) => <td key={c.key} className={MONEDA.includes(c.key) ? 'num' : ''}>{MONEDA.includes(c.key) ? bs(fila[c.key]) : fila[c.key] ?? '—'}</td>)}</tr>)}</tbody>
            </table></div>
          )}
        </section>
      ))}
    </>
  )
}

